import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/users/*")
public class UserSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Connection pool - reuses connections
    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
    }

    // Input normalization - strips null bytes and trims
    private String normalizeInput(String input) {
        if (input == null) return "";
        return input.replace("\0", "").trim();
    }

    // Audit logging for compliance
    private void auditLog(HttpServletRequest req, String action, String detail) {
        String remoteAddr = req.getHeader("X-Forwarded-For");
        if (remoteAddr == null) remoteAddr = req.getRemoteAddr();
        log.info(String.format("AUDIT|%s|%s|%s|%s", remoteAddr, req.getSession().getId(), action, detail));
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        resp.setContentType("application/json");
        String pathInfo = req.getPathInfo();

        if ("/search".equals(pathInfo)) {
            handleSearch(req, resp);
        } else if ("/detail".equals(pathInfo)) {
            handleDetail(req, resp);
        } else {
            resp.setStatus(404);
            resp.getWriter().write("{\"error\":\"not found\"}");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws java.io.IOException {
        String department = normalizeInput(req.getParameter("dept"));
        String nameFilter = normalizeInput(req.getParameter("name"));
        String sortCol = normalizeInput(req.getParameter("sort"));

        if (department.isEmpty()) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"dept parameter required\"}");
            return;
        }

        // Validate sort column against whitelist
        List<String> allowedSorts = Arrays.asList("last_name", "first_name", "hire_date", "employee_id");
        if (sortCol.isEmpty() || !allowedSorts.contains(sortCol)) {
            sortCol = "last_name";
        }

        // Build query - department uses parameterized query, name uses LIKE
        String sql = "SELECT employee_id, first_name, last_name, email, department " +
                     "FROM employees WHERE department = ? ";

        if (!nameFilter.isEmpty()) {
            // Append name filter - developer assumed normalizeInput was sufficient
            sql += "AND (first_name LIKE '%" + nameFilter + "%' OR last_name LIKE '%" + nameFilter + "%') ";
        }

        sql += "ORDER BY " + sortCol + " LIMIT 50";

        auditLog(req, "SEARCH", "dept=" + department + ",name=" + nameFilter);

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, department);
            ResultSet rs = stmt.executeQuery();

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "  {\"id\":%d,\"name\":\"%s %s\",\"email\":\"%s\",\"dept\":\"%s\"}",
                    rs.getInt("employee_id"),
                    rs.getString("first_name"),
                    rs.getString("last_name"),
                    rs.getString("email"),
                    rs.getString("department")));
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }

    private void handleDetail(HttpServletRequest req, HttpServletResponse resp)
            throws java.io.IOException {
        String empId = normalizeInput(req.getParameter("id"));
        if (empId.isEmpty()) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"id required\"}");
            return;
        }

        String sql = "SELECT employee_id, first_name, last_name, email, department, hire_date " +
                     "FROM employees WHERE employee_id = ?";

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, empId);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                resp.getWriter().write(String.format(
                    "{\"id\":%d,\"first_name\":\"%s\",\"last_name\":\"%s\",\"email\":\"%s\",\"dept\":\"%s\",\"hired\":\"%s\"}",
                    rs.getInt("employee_id"), rs.getString("first_name"),
                    rs.getString("last_name"), rs.getString("email"),
                    rs.getString("department"), rs.getString("hire_date")));
            } else {
                resp.setStatus(404);
                resp.getWriter().write("{\"error\":\"not found\"}");
            }
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }
}
